-- Bolton Vouched: new categories (eight new trades; Cleaning services, Catering services, Car valeting and Windows, doors & glazing renamed) for the LIVE Supabase project
-- (mmarznvndvbwyhhtbfjy).
-- Paste ALL of this into Supabase -> SQL Editor -> New query -> Run, once. It is one transaction: if anything
-- fails, nothing is changed. Confirm the 'destructive operation' warning (it comes from 'create or replace' and
-- 'drop ... if exists' lines; no data is deleted). The checks at the end fail the whole paste if a piece is missing.
-- Generated by scripts/build-production-sql.mjs from supabase/migrations/20261012000039_new_categories.sql .. 20261012000039_new_categories.sql;
-- do not edit by hand.
begin;

-- Run the launch hardening script (docs/launch/launch-hardening-production.sql) first: this stops (changing nothing) if it hasn't been.
do $requires$
begin
  if not exists (select 1 from supabase_migrations.schema_migrations where version = '20261012000038') then
    raise exception 'Run the launch hardening script (docs/launch/launch-hardening-production.sql) first: migration 20261012000038 is not recorded';
  end if;
end
$requires$;

-- ==== 20261012000039_new_categories.sql
-- New trades requested by the owner before launch (EV chargers & solar, carpets, gutter cleaning, kitchen fitters,
-- fitted bedrooms, window cleaners, bathroom fitters, driveways), and two renames so
-- the names say what the categories already cover. Slugs (and so /c/... addresses and listings) stay the same.
-- Idempotent: safe to run again.
insert into public.categories (group_id, slug, name, requirement, guidance_note)
select g.id, v.slug, v.name, 'none'::public.category_requirement, v.note
from (values
  ('ev-solar', 'EV chargers & solar', 'For solar panels, ask if the installer is MCS certified: it''s needed to be paid for the power you export. EV chargers should be fitted by a registered electrician (NICEIC or NAPIT).'),
  ('carpets', 'Carpets', null),
  ('gutter-cleaning', 'Gutter cleaning', null),
  ('kitchen-fitter', 'Kitchen fitter', null),
  ('bedrooms-wardrobes', 'Fitted bedrooms & wardrobes', null),
  ('window-cleaner', 'Window cleaner', null),
  ('bathroom-fitter', 'Bathroom fitter', null),
  ('driveways-paving', 'Driveways & paving', null)
) as v(slug, name, note)
join public.category_groups g on g.slug = 'home-trades'
on conflict (slug) do nothing;

update public.categories set name = 'Cleaning services' where slug = 'cleaner';
update public.categories set name = 'Catering services' where slug = 'caterer';
update public.categories set name = 'Car valeting' where slug = 'valeting';
-- Fitting and repairing windows are one trade in practice: one category, now with the home trades.
update public.categories
set name = 'Windows, doors & glazing', group_id = (select id from public.category_groups where slug = 'home-trades')
where slug = 'window-door-repair';

insert into supabase_migrations.schema_migrations (version, name) values ('20261012000039', 'new_categories') on conflict do nothing;

-- ==================================================================== verification
-- Fails (and so rolls back everything above) if any piece is missing.
do $verify$
begin
  if (select count(*) from public.categories where active and slug in ('ev-solar', 'carpets', 'gutter-cleaning', 'kitchen-fitter',
      'bedrooms-wardrobes', 'window-cleaner', 'bathroom-fitter', 'driveways-paving')) <> 8 then
    raise exception 'New categories check failed: one of the eight new trades is missing';
  end if;
  if not exists (select 1 from public.categories where slug = 'cleaner' and name = 'Cleaning services')
     or not exists (select 1 from public.categories where slug = 'caterer' and name = 'Catering services')
     or not exists (select 1 from public.categories where slug = 'valeting' and name = 'Car valeting')
     or not exists (select 1 from public.categories c join public.category_groups g on g.id = c.group_id
                    where c.slug = 'window-door-repair' and c.name = 'Windows, doors & glazing' and g.slug = 'home-trades') then
    raise exception 'New categories check failed: a renamed category is missing its new name';
  end if;
end
$verify$;

commit;

select 'New categories applied' as result,
       (select count(*) from supabase_migrations.schema_migrations where version in ('20261012000039')) as migrations_recorded;
